  @Test
  def upsampleFloatsKeepsEndpointsAndLength(): Unit = {
    val source = Array(3.5f, -7.25f, 11.0f, 0.5f)
    val result = Lut2D.upsample(source, 13)
    assertEquals(13, result.length)
    assertEquals(source.head, result.head, 1e-6f)
    assertEquals(source.last, result.last, 1e-6f)
  }

  @Test
  def upsampleFloatsHandlesDegenerateInput(): Unit = {
    assertArrayEquals(Array(4.5f, 4.5f, 4.5f), Lut2D.upsample(Array(4.5f), 3), 1e-6f)
    assertArrayEquals(Array(1.5f), Lut2D.upsample(Array(1.5f, 9.5f), 1), 1e-6f)
    assertArrayEquals(Array(1.5f, 9.5f), Lut2D.upsample(Array(1.5f, 9.5f), 2), 1e-6f)
  }

  @Test
  def upsampleFloatsRejectsInvalidArguments(): Unit = {
    assertThrows(classOf[IllegalArgumentException], () => Lut2D.upsample(Array.empty[Float], 4))
    assertThrows(classOf[IllegalArgumentException], () => Lut2D.upsample(Array(1.0f, 2.0f), 0))
  }
}
